55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.transaction.Transactional;
58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    public OwnerRestControllerV1(ClinicService clinicService,
79	                                 OwnerMapper ownerMapper,
80	                                 PetMapper petMapper,
81	                                 VisitMapper visitMapper) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	    }
87	
88	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
89	    @Override
90	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
91	        Collection<Owner> owners;
92	        if (lastName != null) {
93	            owners = this.clinicService.findOwnerByLastName(lastName);
94	        } else {
95	            owners = this.clinicService.findAllOwners();
96	        }
97	        if (owners.isEmpty()) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
106	        Owner owner = this.clinicService.findOwnerById(ownerId);
107	        if (owner == null) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        HttpHeaders headers = new HttpHeaders();
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
119	        owner.setTelephone(normalizedTelephone);
120	        owner.setEmail(normalizeEmail(owner.getEmail()));
121	        owner.setAddress(normalizeAddress(owner.getAddress()));
122	        validatePostcode(owner.getCity(), owner.getPostcode());
123	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
124	        if (effectiveRegistrationDate == null) {
125	            effectiveRegistrationDate = LocalDate.now();
126	        } else if (effectiveRegistrationDate.isAfter(LocalDate.now())) {
127	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
128	                "registrationDate must not be later than the current server date");
129	        }
130	        effectiveRegistrationDate = rollToBusinessDay(effectiveRegistrationDate);
131	        owner.setRegistrationDate(effectiveRegistrationDate);
132	        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= DAILY_CREATE_LIMIT) {
133	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
134	                "the maximum number of owners that may be created today has been reached");
135	        }
136	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
137	        // The household id is deterministic (derived from the last name and postcode), so every
138	        // owner is keyed to its household automatically, regardless of creation order.
139	        this.clinicService.assignHousehold(owner);
140	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner.getHouseholdId(), null);
141	        if (householdInUse && !sharesHousehold) {
142	            throw new ResponseStatusException(HttpStatus.CONFLICT,
143	                "an owner in the same household already exists");
144	        }
145	        if (isIdentityKeyInUse(ownerMapper.toIdentityKey(owner), null)) {
146	            throw new ResponseStatusException(HttpStatus.CONFLICT,
147	                "an owner with the same identity already exists");
148	        }
149	        if (countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
150	            throw new ResponseStatusException(HttpStatus.CONFLICT,
151	                "city has reached its maximum number of owners");
152	        }
153	        owner.setCustomerCode(customerCodeFor(owner));
154	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
155	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
156	        owner.setBulkSignupWarning(
157	            countOwnersRegisteredOn(effectiveRegistrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
158	        // A declared household member (one created with 'sharesHousehold' that joins an existing
159	        // household) is not a suspected duplicate, so it is never flagged as a possible duplicate.
160	        boolean declaredHouseholdMember = sharesHousehold && householdInUse;
161	        Owner softDuplicate = declaredHouseholdMember ? null : findPossibleDuplicate(owner);
162	        owner.setPossibleDuplicate(softDuplicate != null);
163	        owner.setPossibleDuplicateOf(softDuplicate == null ? null : softDuplicate.getId());
164	        this.clinicService.saveOwner(owner);
165	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
166	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
167	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
168	            ownerDto.getMembershipLevel());
169	        headers.setLocation(UriComponentsBuilder.newInstance()
170	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
171	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Override
176	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
177	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
178	        if (currentOwner == null) {
179	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	        }
181	        currentOwner.setAddress(ownerFieldsDto.getAddress());
182	        currentOwner.setCity(ownerFieldsDto.getCity());
183	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
184	        currentOwner.setLastName(ownerFieldsDto.getLastName());
185	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
186	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
187	        this.clinicService.saveOwner(currentOwner);
188	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
189	    }
190	
191	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
192	    @Transactional
193	    @Override
194	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
195	        Owner owner = this.clinicService.findOwnerById(ownerId);
196	        if (owner == null) {
197	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
198	        }
199	        this.clinicService.deleteOwner(owner);
200	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
206	        Owner owner = this.clinicService.findOwnerById(ownerId);
207	        if (owner == null) {
208	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
209	        }
210	        HttpHeaders headers = new HttpHeaders();
211	        Pet pet = petMapper.toPet(petFieldsDto);
