267	
268	    /**
269	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where REGION is
270	     * the region derived from the owner's postcode (preferring the postcode, falling back to the
271	     * city table, else {@code 'UNKNOWN'}; see {@link OwnerMapper#regionOf(Owner)}) and HASH8 is the
272	     * first 8 upper-case hex characters of the SHA-256 digest of the owner's normalized E.164
273	     * telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The code carries no
274	     * sequence number, so it is a stable function of the owner's region and telephone/last-name
275	     * identity rather than of creation order.
276	     *
277	     * @param owner the owner being created, with its telephone already normalized to E.164 form
278	     * @return the assigned customer code
279	     */
280	    private String customerCodeFor(Owner owner) {
281	        String region = ownerMapper.regionOf(owner);
282	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName()).substring(0, 8);
283	        return region + "-" + hash8;
284	    }
285	
286	    /**
287	     * Computes the SHA-256 digest of the UTF-8 bytes of {@code value} and renders it as an
288	     * upper-case hex string.
289	     *
290	     * @param value the string to hash
291	     * @return the full SHA-256 digest as upper-case hex
292	     */
293	    private static String sha256UpperHex(String value) {
294	        try {
295	            byte[] digest = MessageDigest.getInstance("SHA-256")
296	                .digest(value.getBytes(StandardCharsets.UTF_8));
297	            StringBuilder sb = new StringBuilder(digest.length * 2);
298	            for (byte b : digest) {
299	                sb.append(String.format("%02X", b));
300	            }
301	            return sb.toString();
302	        } catch (NoSuchAlgorithmException ex) {
303	            throw new IllegalStateException("SHA-256 not available", ex);
304	        }
305	    }
306	
307	    /**
308	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
309	     * owner's city already contains this many owners.
310	     */
311	    private static final int CITY_CAPACITY = 50;
312	
313	    /**
314	     * The maximum number of owners that may be created on a single day. A create is rejected with
315	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
316	     * {@code registrationDate}.
317	     */
318	    private static final int DAILY_CREATE_LIMIT = 100;
319	
320	    /**
321	     * The number of owners that must already have been created for the current day before a new
322	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
323	     * owners already carry today's {@code registrationDate}.
324	     */
325	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
326	
327	    /**
328	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday or
329	     * Sunday is moved forward to the following Monday, while a date already on a weekday is returned
330	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
331	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
332	     * falls on a business day.
333	     *
334	     * @param date the effective registration date
335	     * @return the same date when it is a weekday, otherwise the following Monday
336	     */
337	    private static LocalDate rollToBusinessDay(LocalDate date) {
338	        return switch (date.getDayOfWeek()) {
339	            case SATURDAY -> date.plusDays(2);
340	            case SUNDAY -> date.plusDays(1);
341	            default -> date;
342	        };
343	    }
344	
345	    /**
346	     * Counts the existing owners whose {@code registrationDate} equals the given (already
347	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
348	     * business day. Called before a new owner is saved, so the returned value reflects the number of
349	     * owners created for that day prior to this create.
350	     *
351	     * @param date the adjusted business-day registration date to count against
352	     * @return the number of existing owners registered on that date
353	     */
354	    private int countOwnersRegisteredOn(LocalDate date) {
355	        return (int) this.clinicService.findAllOwners().stream()
356	            .filter(existing -> date.equals(existing.getRegistrationDate()))
357	            .count();
358	    }
359	
360	    /**
361	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
362	     *
363	     * @param city the city to count owners for
364	     * @return the number of existing owners in that city
365	     */
366	    private int countOwnersInCity(String city) {
367	        return (int) this.clinicService.findAllOwners().stream()
368	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
369	            .count();
370	    }
371	
372	    /**
373	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
374	     * the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}).
375	     *
376	     * @param customerCode     the owner's assigned customer code
377	     * @param registrationDate the owner's registration date
378	     * @return the assigned membership number
379	     */
380	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
381	        String yy = String.format("%02d", registrationDate.getYear() % 100);
382	        return String.format("%s-M%s", customerCode, yy);
383	    }
384	
385	    /**
386	     * Counts the existing owners that already share the given first name and last name, comparing
387	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
388	     * the number of namesakes that existed prior to this create.
389	     *
390	     * @param firstName the new owner's first name
391	     * @param lastName  the new owner's last name
392	     * @return the number of existing owners with the same first and last name
393	     */
394	    private int countNamesakes(String firstName, String lastName) {
395	        int count = 0;
396	        for (Owner existing : this.clinicService.findAllOwners()) {
397	            if (firstName.equalsIgnoreCase(existing.getFirstName())
398	                && lastName.equalsIgnoreCase(existing.getLastName())) {
399	                count++;
400	            }
401	        }
402	        return count;
403	    }
404	
405	    /**
406	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
407	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
408	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
409	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
410	     * string is what gets stored and returned.
411	     *
412	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
413	     *
414	     * <p>Once in E.164 form the national-number length is validated against the country code: a
415	     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
416	     * number exactly 10 (see {@link E164PhoneNumbers#NATIONAL_LENGTHS}). Country codes without a configured
417	     * rule are accepted on the general 8-to-15 digit length alone.
418	     *
419	     * @param telephone the raw telephone value supplied by the client
420	     * @return the normalized E.164 telephone number
421	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
422	     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
423	     *                                 after the {@code '+'}, or the wrong national-number length for
424	     *                                 its country code)
425	     */
426	    private static String normalizeTelephone(String telephone) {
427	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
428	        String digits;
429	        if (cleaned.startsWith("+")) {
430	            digits = cleaned.substring(1);
431	        } else {
432	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
433	            digits = "61" + national;
434	        }
435	        if (!digits.matches("[0-9]{8,15}")) {
436	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
437	                "telephone could not be normalized to a valid E.164 number");
438	        }
439	        validateNationalNumberLength(digits);
440	        return "+" + digits;
441	    }
442	
443	    /**
444	     * Validates the national-number length of an E.164 number (its digits, without the leading
445	     * {@code '+'}) against its country code. The longest dialling code that prefixes the number (see
446	     * {@link E164PhoneNumbers#countryCode}) selects the rule; if none is configured the number passes
447	     * (only the general 8-to-15 digit rule applies).
448	     *
449	     * @param digits the E.164 digits without the leading {@code '+'}
450	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
451	     *                                 digits does not match the country code's required length
452	     */
453	    private static void validateNationalNumberLength(String digits) {
454	        E164PhoneNumbers.countryCode(digits)
455	            .ifPresent(code -> {
456	                int nationalLength = digits.length() - code.length();
457	                int required = E164PhoneNumbers.NATIONAL_LENGTHS.get(code);
458	                if (nationalLength != required) {
459	                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
460	                        "telephone must have " + required
461	                            + " national digits for country code +" + code);
462	                }
463	            });
464	    }
465	
466	    /**
467	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
468	     * containing at least one dot, none of the three sections containing whitespace or an
469	     * additional {@code @}.
470	     */
471	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
472	
473	    /**
474	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
475	     * (email is optional). When a value is supplied it must be a syntactically valid address; the
476	     * value is then stored and returned lower-cased.
477	     *
478	     * @param email the raw email value supplied by the client, possibly {@code null}
479	     * @return the lower-cased email, or {@code null} when none was supplied
480	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
481	     *                                 is not a syntactically valid address
482	     */
483	    private static String normalizeEmail(String email) {
484	        if (email == null) {
485	            return null;
486	        }
487	        if (!EMAIL_PATTERN.matcher(email).matches()) {
488	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
489	                "email must be a syntactically valid address");
490	        }
491	        return email.toLowerCase(Locale.ROOT);
492	    }
493	
494	    /**
495	     * Fixed region-to-inclusive-postcode-range table. The postcode of an owner whose city maps to a
496	     * known region (via {@link OwnerMapper#CITY_REGION}) must fall within its region's range: NSW
497	     * 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}} inclusive.
498	     */
499	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
500	        "NSW", new int[] {2000, 2099},
501	        "VIC", new int[] {3000, 3099},
502	        "QLD", new int[] {4000, 4099});
503	
504	    /**
505	     * Validates an owner's optional postcode against the city's region. Postcode is validated only
506	     * when present ({@code null} is accepted, keeping the request contract backward-compatible). The
507	     * four-digit format is enforced by request validation; here the value is range-checked: when the
508	     * city maps to a known region (via {@link OwnerMapper#CITY_REGION}) the postcode must fall within
509	     * that region's inclusive range (see {@link #REGION_POSTCODE_RANGES}). A city with no known region
510	     * accepts any four-digit postcode.
511	     *
512	     * @param city     the owner's city
513	     * @param postcode the owner's postcode, possibly {@code null}
514	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a supplied postcode is
515	     *                                 out of range for the city's region
516	     */
517	    private static void validatePostcode(String city, String postcode) {
518	        if (postcode == null) {
519	            return;
520	        }
521	        String region = OwnerMapper.CITY_REGION.get(city);
522	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
523	        if (range == null) {
524	            return;
525	        }
526	        int value = Integer.parseInt(postcode);
527	        if (value < range[0] || value > range[1]) {
528	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
529	                "postcode " + postcode + " is not valid for region " + region);
530	        }
531	    }
532	
533	    /**
534	     * Common street-type abbreviations expanded to their full word during address normalization.
535	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
536	     */
537	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
538	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
539	
540	    /**
541	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
542	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
543	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
544	     * {@code AVE -> AVENUE}). This normalized value is what gets stored and returned.
545	     *
546	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
547	     *
548	     * @param address the raw address supplied by the client, possibly {@code null}
549	     * @return the normalized address
550	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
551	     *                                 after normalization (required field)
552	     */
553	    private static String normalizeAddress(String address) {
554	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
555	        if (collapsed.isEmpty()) {
556	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
557	                "address must not be blank");
558	        }
559	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
560	        StringBuilder normalized = new StringBuilder();
561	        for (int i = 0; i < tokens.length; i++) {
562	            if (i > 0) {
563	                normalized.append(' ');
564	            }
565	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
566	        }
567	        return normalized.toString();
568	    }
569	
570	    /**
571	     * Determines whether the given whole identity key already belongs to any owner other than the
572	     * one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g. on
573	     * create). The key is derived in one place — {@link OwnerMapper#toIdentityKey(Owner)}, the same
574	     * method that builds the {@code identityKey} returned on the DTO — so the value governing the
575	     * 409 is exactly the value clients see. Only an exact full-key match counts as a duplicate.
576	     *
577	     * @param identityKey the identity key to look for
578	     * @param excludeId   id of an owner to ignore during the check, or {@code null} for none
579	     * @return {@code true} if another owner already has the same identity key
580	     */
581	    private boolean isIdentityKeyInUse(String identityKey, Integer excludeId) {
582	        for (Owner existing : this.clinicService.findAllOwners()) {
583	            if (excludeId != null && excludeId.equals(existing.getId())) {
584	                continue;
585	            }
586	            if (identityKey.equals(ownerMapper.toIdentityKey(existing))) {
587	                return true;
588	            }
589	        }
590	        return false;
591	    }
592	
593	    /**
594	     * Finds the existing owner that the given (not-a-hard-duplicate) new owner is a possible
595	     * (soft) duplicate of: one that shares the new owner's last name (compared case-insensitively)
596	     * and postcode while carrying a <em>different</em> normalized telephone. A hard duplicate
597	     * (identical identity key) has already been rejected with a 409 before this runs, so this
598	     * flags only the softer last-name/postcode overlap. The match with the lowest id is returned
599	     * so the result is deterministic when several owners qualify.
600	     *
601	     * @param owner the new owner being created, with its telephone already normalized
602	     * @return the matching existing owner, or {@code null} when none qualifies
603	     */
604	    private Owner findPossibleDuplicate(Owner owner) {
605	        if (owner.getLastName() == null || owner.getPostcode() == null) {
606	            return null;
607	        }
608	        return this.clinicService.findAllOwners().stream()
609	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
610	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
611	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
612	            .min(Comparator.comparingInt(Owner::getId))
613	            .orElse(null);
614	    }
615	
616	}
